&lt;li data-leveltext=&quot;●&quot; data-font=&quot;Arial&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335551500&amp;quot;:2500134,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Arial&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;●&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Develop the product strategy for experiences &amp;amp; capability that help acquire &amp;amp; engage members, with a focus on seamless experiences from acquisition to ongoing member engagement that serve new &amp;amp; diverse audiences and drive monetization growth.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
