&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;31&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Help manage&amp;nbsp;our vertical’s&amp;nbsp;roadmap,&amp;nbsp;together with your product management colleagues and&amp;nbsp;in alignment with the DBSP&amp;nbsp;Heads,&amp;nbsp;our&amp;nbsp;Tech Leads,&amp;nbsp;and their teams&amp;nbsp;of software engineers,&amp;nbsp;to ensure&amp;nbsp;efficient&amp;nbsp;utilization&amp;nbsp;of resources and&amp;nbsp;a delivery plan in line with our quarterly goals&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:160}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;31&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Apply&amp;nbsp;product lifecycle management principles to the development of&amp;nbsp;our&amp;nbsp;products,&amp;nbsp;ensuring&amp;nbsp;steady improvement of the evolving product&amp;nbsp;in terms of cost, quality, and efficiency,&amp;nbsp;while&amp;nbsp;maintaining&amp;nbsp;data consistency across versions&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:160}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
